```cypher
MATCH (so:SalesOrder)-[:IN_TERRITORY]->(t:Territory)
WHERE t.country_code = 'CA' AND date_part('year', so.order_date) = 2023
MATCH (so)-[line:HAS_LINE]->(sold:Product)
// Direct sales of FR-R92R-62
OPTIONAL MATCH (sold)-[path:EXPLODES*1..6]->(target:Product)
WHERE target.product_number = 'FR-R92R-62'
  AND path.valid_from <= so.order_date
  AND (path.valid_to IS NULL OR path.valid_to >= so.order_date)
WITH so, line, sold, target, path
// If target is null, it means sold IS the target (direct sale)
// If target is not null, it means sold contains target
// We need to sum:
// 1. If sold.product_number = 'FR-R92R-62', add line.order_qty
// 2. If target.product_number = 'FR-R92R-62', add line.order_qty * path.qty
// Note: EXPLODES qty is already the total quantity per unit of the root.
// So for a path sold -> ... -> target, the quantity of target in one sold is path.qty.
// Total demand = sum over all lines of (order_qty * (1 if sold is target else 0) + order_qty * path.qty if target is found))
// However, a product can be both sold directly AND contained in another sold product in the same order? 
// The question asks for "total demand ... from the orders". 
// Demand = (Units sold directly) + (Units contained in other products sold).
// If I sell 1 bike, and the bike contains 1 frame, demand for frame is 1 (contained).
// If I sell 1 frame directly, demand for frame is 1 (direct).
// If I sell 1 bike and 1 frame, demand is 1 (from bike) + 1 (direct) = 2.

// Let's restructure to avoid double counting or missing cases.
// For each order line (so, line, sold):
// Contribution to FR-R92R-62 demand:
// A. If sold.product_number = 'FR-R92R-62': line.order_qty
// B. If sold contains FR-R92R-62: line.order_qty * (sum of qty of all paths from sold to FR-R92R-62 valid on so.order_date)

// Since EXPLODES is materialized and sums over paths, there should be at most one EXPLODES edge from sold to target for a given interval?
// The schema says: "one row per root, item at any level below it ... and interval of constant qty".
// So for a specific date, there is at most one EXPLODES edge from sold to target.
// So we can just match the edge.

MATCH (so:SalesOrder)-[:IN_TERRITORY]->(t:Territory)
WHERE t.country_code = 'CA' AND date_part('year', so.order_date) = 2023
MATCH (so)-[line:HAS_LINE]->(sold:Product)

// Case 1: Direct sale
OPTIONAL MATCH (sold_direct:Product)
WHERE sold_direct.product_number = 'FR-R92R-62' AND sold_direct.product_id = sold.product_id

// Case 2: Contained in sold
OPTIONAL MATCH (sold)-[exp:EXPLODES]->(target:Product)
WHERE target.product_number = 'FR-R92R-62'
  AND exp.valid_from <= so.order_date
  AND (exp.valid_to IS NULL OR exp.valid_to >= so.order_date)

WITH so, line, sold, sold_direct, exp
RETURN sum(
    CASE 
        WHEN sold_direct IS NOT NULL THEN line.order_qty 
        ELSE 0 
    END + 
    CASE 
        WHEN exp IS NOT NULL THEN line.order_qty * exp.qty 
        ELSE 0 
    END
) AS total_demand
